package threexui

import (
	"bytes"
	"context"
	"encoding/json"
	"net/http"
	"os"
	"testing"
	"time"
)

// TestLive3XUIRecentOnlineContract verifies the actual official HTTP reader in
// a new network-none instance. Its raw-template fixture is not a writable
// Runtime implementation and does not certify configuration hot updates. Only
// the official provider starts Xray; traffic is generated by its HTTP probe.
// IP absence is valid when the provider does not persist loopback observations.
// No current-device snapshot, connection end time or Core integration is claimed.
func TestLive3XUIRecentOnlineContract(t *testing.T) {
	optIn := os.Getenv("CHIRAL_3XUI_TEST_WRITE")
	if optIn == "" {
		t.Skip("set CHIRAL_3XUI_TEST_WRITE=isolated-empty-instance to enable the official recent-online contract")
	}
	if optIn != "isolated-empty-instance" {
		t.Fatal("recent-online contract requires explicit isolated-empty-instance opt-in")
	}
	liveHTTPProbeRequireLoopbackNamespace(t)
	baseURL, tokenFile := os.Getenv("CHIRAL_3XUI_TEST_URL"), os.Getenv("CHIRAL_3XUI_TEST_TOKEN_FILE")
	if baseURL == "" || tokenFile == "" {
		t.Fatal("recent-online contract requires the isolated URL and token file")
	}
	client, err := New(Config{BaseURL: baseURL, Token: readLive3XUIToken(t, tokenFile), Timeout: 15 * time.Second})
	if err != nil {
		t.Fatal("cannot construct the isolated recent-online client")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 3*time.Minute)
	defer cancel()
	liveHTTPProbeRequireEmpty(t, ctx, client)
	baseline, err := client.ReadAssembledConfig(ctx)
	if err != nil {
		t.Fatal("cannot read the empty recent-online fixture configuration")
	}
	liveWriteRequireAPIOnly(t, baseline)
	identity, err := liveUpdateWaitState(ctx, client, "running")
	if err != nil {
		t.Fatal("cannot confirm the recent-online provider identity")
	}
	caps, err := client.DiscoverCapabilities(ctx)
	if err != nil {
		t.Fatal("cannot discover the official recent-online capabilities")
	}
	for _, capability := range []Capability{CapabilityOutboundProbe, CapabilityXrayUpdate, CapabilityClientsOnlineByGUID, CapabilityClientIPsByGUID} {
		if !caps.Supports(capability) {
			t.Fatal("official provider lacks a required recent-online fixture operation")
		}
	}
	snapshot, err := client.ReadXrayTemplate(ctx)
	if err != nil || snapshot.OutboundTestURL == "" {
		t.Fatal("cannot read a restorable recent-online template")
	}
	liveWriteRequireAPIOnly(t, snapshot.Config)
	prefix := "chiral-recent-online-" + liveWriteRandomID(t)
	targetURL := "http://8.8.8.8/" + prefix
	body := bytes.Repeat([]byte("chiral-recent-online|"), 4096)
	origin := liveHTTPProbeStartOriginWithBody(t, "8.8.8.8", "/"+prefix, body)
	defer origin.close(t)
	accounts := make([]liveBootstrapAccount, 3)
	ports := make(map[int]bool)
	credentials := make(map[string]bool)
	candidate := baseline
	for i, suffix := range []string{"requested", "excluded", "unused"} {
		account := liveBootstrapAccount{Prefix: prefix + "-" + suffix, Credential: liveWriteUUID(t), Port: liveProjectionFreePort(t)}
		if ports[account.Port] || credentials[account.Credential] {
			t.Fatal("recent-online fixture identities or ports collided")
		}
		ports[account.Port], credentials[account.Credential] = true, true
		accounts[i] = account
		candidate = liveBootstrapConfig(t, candidate, account, origin.address)
	}
	// Register exact ownership/snapshot cleanup before even disabled metadata.
	defer liveBootstrapRestore(t, client, identity, snapshot, baseline, targetURL, []json.RawMessage{candidate}, accounts)
	for _, account := range accounts {
		liveBootstrapAddMetadata(t, ctx, client, account)
	}
	liveBootstrapRequireObjects(t, ctx, client, accounts)
	liveBootstrapRequireSnapshots(t, ctx, client, snapshot.Config, baseline, snapshot.OutboundTestURL)
	if err := client.UpdateXrayTemplate(ctx, XrayTemplate{Config: candidate, OutboundTestURL: targetURL}); err != nil {
		t.Fatal("cannot apply the owned isolated recent-online fixture")
	}
	liveBootstrapRequireConfig(t, ctx, client, candidate, targetURL)
	allEmails := []string{accounts[0].email(), accounts[1].email(), accounts[2].email()}
	before, err := client.ReadRecentOnline(ctx, identity.PanelGUID, allEmails)
	if err != nil || len(before) != len(allEmails) {
		t.Fatal("cannot read the official recent-online baseline")
	}
	for i, observation := range before {
		if observation.Email != allEmails[i] || observation.ObservedOnline || len(observation.IPs) != 0 {
			t.Fatal("a never-used fixture identity already had an observation")
		}
	}
	probe := func(probeCtx context.Context, account liveBootstrapAccount) {
		hits, written := origin.hits.Load(), origin.written.Load()
		result, err := client.ProbeOutbound(probeCtx, liveHTTPProbeOutbound(t, account.Prefix+"-client", account.Credential, account.Port), nil, targetURL)
		if err != nil || result.HTTPStatus != http.StatusOK || origin.hits.Load() != hits+1 ||
			origin.written.Load() != written+int64(len(body)) || origin.invalid.Load() != 0 || origin.writeErrors.Load() != 0 {
			t.Fatal("recent-online fixture probe did not complete its authenticated origin response")
		}
	}
	pollCtx, pollCancel := context.WithTimeout(ctx, 45*time.Second)
	defer pollCancel()
	for {
		// Both identities have real traffic, so excluding the second from a
		// later request is a positive isolation test, not an empty-list pass.
		probe(pollCtx, accounts[0])
		probe(pollCtx, accounts[1])
		observations, err := client.ReadRecentOnline(pollCtx, identity.PanelGUID, allEmails)
		if err != nil || len(observations) != len(allEmails) {
			t.Fatal("official recent-online HTTP polling failed or returned a partial request set")
		}
		if observations[2].Email != allEmails[2] || observations[2].ObservedOnline || len(observations[2].IPs) != 0 {
			t.Fatal("traffic was attributed to a never-used fixture identity")
		}
		if observations[0].Email == allEmails[0] && observations[1].Email == allEmails[1] &&
			observations[0].ObservedOnline && observations[1].ObservedOnline {
			break
		}
		select {
		case <-pollCtx.Done():
			t.Fatal("official recent-online cache did not observe both traffic-producing identities")
		case <-time.After(500 * time.Millisecond):
		}
	}
	t.Log("recent_online_positive_verified=true authenticated_origin_verified=true")
	selected, err := client.ReadRecentOnline(ctx, identity.PanelGUID, []string{allEmails[0], allEmails[2]})
	if err != nil || len(selected) != 2 || selected[0].Email != allEmails[0] || !selected[0].ObservedOnline ||
		selected[1].Email != allEmails[2] || selected[1].ObservedOnline || len(selected[1].IPs) != 0 {
		t.Fatal("official recent-online results violated the requested credential whitelist")
	}
	for _, observation := range selected {
		if observation.Email == allEmails[1] {
			t.Fatal("an active but unrequested identity escaped the reader whitelist")
		}
	}
	// The result type carries an observation flag only. It cannot certify that
	// the unused identity is offline, that a returned IP is currently connected,
	// or that the provider enumerated a complete device set.
	liveHTTPProbeRequireIdentity(t, ctx, client, identity)
	liveBootstrapRequireObjects(t, ctx, client, accounts)
	liveBootstrapRequireConfig(t, ctx, client, candidate, targetURL)
	t.Log("recent_online_whitelist_verified=true recent_online_absence_is_unknown=true current_device_snapshot_verified=false positive_ip_observation_verified=false")
	t.Log("http_only_control=true official_http_probe_used=true core_integration_verified=false shadow_allowlist_verified=false")
}
